// Translations of system texts (menus, items, skills, enemies, battle, place names, speaker names):
// lang/<language>_sys.tsv, generated by tools/make_sys.py.
// The texts sit in tables the game reads through pointers or offsets: GR3.MDT (resident, loaded
// once; offsets of the item tables are relocated to absolute pointers at load), the overlays' data
// (field/battle, reloaded whenever the overlay is) and the per-map name tables (MDT chunk
// a0001350, u16 characters, offset + length per string). Every vertical blank the entries still
// holding their original value are redirected to the German text placed in unused low EE RAM
// (offsets wrap around: base + offset is 32-bit arithmetic). Strings the code addresses directly
// are overwritten in place (the tool only emits those that fit).
//
// Lines (tab separated): <kind> <a hex> <b hex> <c hex> <text>
//   g  a = GR3 offset of a pointer to a name, b = GR3 offset of the name, c = FNV-1a 32 of it
//   n  like g; the byte after the pointer holds the name's length
//   d  like g for a description (lines separated by NUL, ends NUL NUL); c = its length, kept in the
//      u16 after the pointer (e: before the pointer, f: not kept); the text is padded to that length
//   c  like b for several lines (separated by NUL)
//   a  a = address of a pointer in overlay data, b = original string, c = hash; field menu encoding
//   b  like a; font codes
//   i  a = address of a string overwritten in place, b = room in bytes, c = hash; font codes
//   j  like i; field menu encoding
//   w  a = GR3 offset of a u32 offset to a NUL-terminated u16 string, b = GR3 offset of the offsets'
//      base, c = the original offset value
//   m  a = key of a map name table (FNV-1a 32 of its data), b = string index; u16, no terminator
//   k  a = GR3 offset of a text overwritten in place, b = its length, c = FNV-1a 32 of the original;
//      the text is given as {hex} bytes of exactly that length (battle calls, advice and tutorial:
//      lang/<language>_btl.tsv from tools/btl_text.py)
// Flight radio messages (lang/<language>_radio.tsv from tools/make_radio.py: English bytes, German
// bytes of the same length, hex) sit inline in the flight script (30000000.MDT, opcode 16 00 00 01
// <u16> <text> 00): EE RAM is scanned a few MB per vertical blank for the opcode and an English text
// is overwritten in place.
// Font codes: space 0x80, ASCII, German/French letters = the patched kana glyphs 0x98..0xB0 + 0x20.
// Field menu encoding: the same glyphs reached through their Shift-JIS codes (FIELD_SJIS).
#include "../common.h"
#include "../memory.h"
#include "../platform/platform.h"
#include <cstring>
#include <map>
#include <string>
#include <unordered_map>
#include <vector>

namespace kernel { bool flight_running(); }

namespace systext {

struct Entry {
    char kind;
    u32 a, b, c;
    std::vector<u8> data;
    u32 len = 0;   // descriptions: length the game keeps (up to the end of the last line)
    u32 addr = 0;  // where the German text lives in EE RAM
};

static std::vector<Entry> g_entries;
static std::unordered_map<u32, std::vector<Entry*>> g_maps;  // map name tables by key
static bool g_loaded = false;
static u32 g_gr3 = 0;  // EE address of GR3.MDT (0: not found yet)
static const u32 AREA = 0x00080000, AREA_END = 0x000FFF00;  // unused low EE RAM (IRQ stack ends below)

// extra letters in glyph order 0x98.. (text_hook.cpp EXTRA): German, then French
static const char* const DE[26] = {"\xC3\xA4", "\xC3\xB6", "\xC3\xBC", "\xC3\x84", "\xC3\x96", "\xC3\x9C", "\xC3\x9F",
    "\xC3\xA0", "\xC3\xA2", "\xC3\xA7", "\xC3\xA9", "\xC3\xA8", "\xC3\xAA", "\xC3\xAB", "\xC3\xAE", "\xC3\xAF",
    "\xC3\xB4", "\xC3\xB9", "\xC3\xBB", "\xC3\x80", "\xC3\x87", "\xC3\x89", "\xC3\x88", "\xC3\x8A", "\xC3\x94",
    "\xC3\x82"};
// their Shift-JIS codes in the field menu: the menu font's character list (GR3.MDT) puts the glyphs
// 0x98.. at ぅうぇえぉおか が ワヲヴヵヶゎヮぢヂ○♪＋−一二三■＿
static const u16 FIELD_SJIS[26] = {0x82A3, 0x82A4, 0x82A5, 0x82A6, 0x82A7, 0x82A8, 0x82A9, 0x82AA,
    0x838F, 0x8392, 0x8394, 0x8395, 0x8396, 0x82EC, 0x838E, 0x82C0, 0x8361, 0x819B, 0x81F4, 0x817B,
    0x817C, 0x88EA, 0x93F1, 0x8E4F, 0x81A1, 0x8151};

static u32 fnv32(const u8* p, size_t n) {
    u32 h = 0x811C9DC5u;
    for (size_t i = 0; i < n; i++) h = (h ^ p[i]) * 0x01000193u;
    return h;
}

// UTF-8 -> game bytes. field: field menu encoding; desc: \n = NUL, ends NUL NUL; wide: u16 units
static std::vector<u8> encode(const std::string& s, bool field, bool desc, bool wide, bool term) {
    std::vector<u8> out;
    auto put = [&](unsigned v) {
        out.push_back((u8)v);
        if (wide) out.push_back((u8)(v >> 8));
    };
    for (size_t i = 0; i < s.size();) {
        unsigned char ch = (unsigned char)s[i];
        if (ch == '\\' && i + 1 < s.size() && s[i + 1] == 'n') {
            put(desc ? 0 : 0x0A);
            i += 2;
            continue;
        }
        if (ch == '{') {  // raw bytes {hex}
            size_t e = s.find('}', i);
            if (e != std::string::npos) {
                for (size_t k = i + 1; k + 1 < e; k += 2) out.push_back((u8)strtoul(s.substr(k, 2).c_str(), nullptr, 16));
                i = e + 1;
                continue;
            }
        }
        if (ch == ' ') { put(field ? 0x20 : 0x80); i++; continue; }
        if (ch < 0x80) { put(ch); i++; continue; }
        int k = -1;
        for (int j = 0; j < 26; j++)
            if (s.compare(i, 2, DE[j]) == 0) k = j;
        if (k >= 0) {
            if (field) { out.push_back((u8)(FIELD_SJIS[k] >> 8)); out.push_back((u8)FIELD_SJIS[k]); }
            else put(0xB8 + k);
            i += 2;
            continue;
        }
        if (s.compare(i, 3, "\xE2\x80\x9E") == 0 || s.compare(i, 3, "\xE2\x80\x9C") == 0) { put('"'); i += 3; continue; }
        if (s.compare(i, 3, "\xE2\x80\x93") == 0) { put('-'); i += 3; continue; }
        if (s.compare(i, 2, "\xC2\xAB") == 0 || s.compare(i, 2, "\xC2\xBB") == 0) { put('"'); i += 2; continue; }
        if (s.compare(i, 2, "\xC5\x93") == 0) { put('o'); put('e'); i += 2; continue; }
        if (s.compare(i, 2, "\xC2\xA0") == 0) { put(field ? 0x20 : 0x80); i += 2; continue; }
        put('?');
        i++;
        while (i < s.size() && ((unsigned char)s[i] & 0xC0) == 0x80) i++;
    }
    if (term) put(0);
    if (desc) put(0);
    return out;
}

static void load() {
    g_loaded = true;
    char line[4096];
    u32 at = AREA;
    std::map<std::vector<u8>, u32> placed;  // identical texts share one copy
    const std::string lang = platform::config().language;
    for (const char* name : {"_sys.tsv", "_btl.tsv"}) {
    FILE* f = lang == "en" ? nullptr : fopen((exe_dir() + "\\lang\\" + lang + name).c_str(), "rb");
    if (!f) continue;
    while (fgets(line, sizeof line, f)) {
        if (line[0] == '#' || line[1] != '\t') continue;
        Entry e;
        e.kind = line[0];
        char* p = line + 2;
        e.a = strtoul(p, &p, 16);
        e.b = strtoul(p + 1, &p, 16);
        e.c = strtoul(p + 1, &p, 16);
        if (*p != '\t') continue;
        std::string text(p + 1);
        while (!text.empty() && (text.back() == '\n' || text.back() == '\r')) text.pop_back();
        bool field = e.kind == 'a' || e.kind == 'j';
        bool wide = e.kind == 'w' || e.kind == 'm';
        bool lines = strchr("defc", e.kind) != nullptr;  // lines separated by NUL
        e.data = encode(text, field, lines, wide, e.kind != 'm' && e.kind != 'k');
        if (lines) {
            e.len = (u32)e.data.size() - 2;
            if (e.kind != 'c' && e.data.size() < e.c + 2) e.data.resize(e.c + 2, 0);  // never shorter than the original
        }
        if (e.kind == 'i' || e.kind == 'j') {
            if (e.data.size() > e.b) continue;  // does not fit
        } else if (e.kind == 'k') {
            if (e.data.size() != e.b) continue;
        } else {
            auto it = placed.find(e.data);
            if (it != placed.end()) e.addr = it->second;
            else {
                at = (at + (wide ? 1 : 0)) & ~(u32)(wide ? 1 : 0);
                if (at + e.data.size() > AREA_END) { log_write(LOG_MAIN, "translation sys: text area full"); break; }
                e.addr = at;
                placed[e.data] = at;
                at += (u32)e.data.size();
            }
        }
        g_entries.push_back(std::move(e));
    }
    fclose(f);
    }
    for (Entry& e : g_entries)
        if (e.kind == 'm') g_maps[e.a].push_back(&e);
    log_write(LOG_MAIN, "translation sys: %zu texts (%u bytes)", g_entries.size(), at - AREA);
}

// GR3.MDT in EE RAM: chunk 7 header at +0x800
static bool gr3_at(u32 a) {
    static const u8 sig[16] = {0x20, 0x09, 0x00, 0xA0, 0x00, 0x13, 0x03, 0x00, 0, 0, 0, 0, 1, 0, 0, 0};
    const u8* p = mem::ee_ptr(a + 0x800);
    return p && memcmp(p, sig, 16) == 0;
}

static void find_gr3() {
    if (g_gr3 && gr3_at(g_gr3)) return;
    g_gr3 = 0;
    static int skip = 0;
    if (skip-- > 0) return;
    skip = 30;
    for (u32 a = 0x100000; a + 0x1000 < mem::RAM_SIZE; a += 0x80)
        if (mem::ram[a + 0x800] == 0x20 && gr3_at(a)) {
            g_gr3 = a;
            log_write(LOG_MAIN, "translation sys: GR3.MDT at %08x", a);
            return;
        }
}

static bool orig_ok(u32 a, u32 hash) {
    const u8* p = mem::ee_ptr(a);
    if (!p) return false;
    size_t n = 0;
    while (n < 1024 && p[n]) n++;
    return fnv32(p, n) == hash;
}

// map name tables: MDT chunk a0001350 (header kept in RAM), data at +0x180:
// count, 0, offset of the length bytes (0x10), offset of the u32 offsets; u16 strings
static void scan_maps() {
    static int skip = 0;
    if (g_maps.empty() || skip-- > 0) return;
    skip = 8;
    for (u32 a = 0x100000; a + 0x400 < mem::RAM_SIZE; a += 0x80) {
        const u8* h = mem::ram + a;
        if (h[0] != 0x50 || h[1] != 0x13 || h[2] != 0x00 || h[3] != 0xA0 || h[12] != 1) continue;
        u32 t = a + 0x180;
        const u8* d = mem::ram + t;
        u32 n, lo, oo;
        memcpy(&n, d, 4);
        memcpy(&lo, d + 8, 4);
        memcpy(&oo, d + 12, 4);
        if (n == 0 || n > 255 || lo != 0x10 || oo != ((0x10 + n + 3) & ~3u)) continue;
        u32 end = 0;
        bool ok = true;
        for (u32 i = 0; i < n && ok; i++) {
            u32 off;
            memcpy(&off, d + oo + 4 * i, 4);
            if (off > 0x10000) ok = false;  // already redirected (or not a name table)
            else end = std::max(end, off + 2u * d[lo + i]);
        }
        if (!ok || t + end > mem::RAM_SIZE) continue;
        auto it = g_maps.find(fnv32(d, end));
        if (it == g_maps.end()) continue;
        for (Entry* e : it->second) {
            if (e->b >= n) continue;
            mem::copy_to_ee(e->addr, e->data.data(), e->data.size());
            mem::wr32(t + oo + 4 * e->b, e->addr - t);
            mem::wr8(t + lo + e->b, (u8)std::min<size_t>(255, e->data.size() / 2));
        }
        static int logged = 0;
        if (logged++ < 40) log_write(LOG_MAIN, "translation sys: name table %08x at %08x", it->first, t);
    }
}

// ---------------------------------------------------------------- flight radio
static std::unordered_map<std::string, std::vector<u8>> g_radio;  // English bytes -> German bytes
static size_t g_radio_min = 0, g_radio_max = 0;

static void load_radio() {
    const std::string lang = platform::config().language;
    FILE* f = lang == "en" ? nullptr : fopen((exe_dir() + "\\lang\\" + lang + "_radio.tsv").c_str(), "rb");
    if (!f) return;
    char line[2048];
    auto unhex = [](const char* p, const char* e) {
        std::string out;
        for (; p + 1 < e; p += 2) out += (char)strtoul(std::string(p, 2).c_str(), nullptr, 16);
        return out;
    };
    while (fgets(line, sizeof line, f)) {
        if (line[0] == '#') continue;
        char* tab = strchr(line, '\t');
        if (!tab) continue;
        char* end = tab + 1;
        while (*end && *end != '\n' && *end != '\r') end++;
        std::string en = unhex(line, tab), de = unhex(tab + 1, end);
        if (en.empty() || en.size() != de.size()) continue;
        g_radio_min = g_radio_min ? std::min(g_radio_min, en.size()) : en.size();
        g_radio_max = std::max(g_radio_max, en.size());
        g_radio[en] = std::vector<u8>(de.begin(), de.end());
    }
    fclose(f);
    log_write(LOG_MAIN, "translation radio: %zu messages", g_radio.size());
}

static void tick_radio() {
    static u32 pos = 0x100000;
    const u32 STEP = 4u << 20;
    u32 end = std::min<u32>(pos + STEP, mem::RAM_SIZE - 8);
    int patched = 0;
    const u8* base = mem::ram;
    for (const u8* p = base + pos; p < base + end;) {
        p = (const u8*)memchr(p, 0x16, (size_t)(base + end - p));
        if (!p) break;
        u32 a = (u32)(p - base);
        p++;
        if (p[0] != 0 || p[1] != 0 || p[2] != 1) continue;
        u32 t = a + 6;
        const u8* q = base + t;
        size_t n = 0, lim = std::min<size_t>(g_radio_max, mem::RAM_SIZE - t - 1);
        while (n <= lim && q[n]) n++;
        if (n < g_radio_min || n > g_radio_max) continue;
        auto it = g_radio.find(std::string((const char*)q, n));
        if (it == g_radio.end()) continue;
        mem::copy_to_ee(t, it->second.data(), it->second.size());
        patched++;
    }
    pos = end >= mem::RAM_SIZE - 8 ? 0x100000 : end;
    if (patched) {
        static int logged = 0;
        if (logged++ < 40) log_write(LOG_MAIN, "translation radio: %d messages replaced (scan up to %08x)", patched, end);
    }
}

void tick() {
    {
        // at most once per display frame of real time (fast forward and the cutscene skip run
        // many vertical blanks per real frame)
        static double last = -1;
        double now = host_time_sec();
        if (now - last < 0.012) return;
        last = now;
    }
    if (!g_loaded) {
        load();
        load_radio();
    }
    if (!g_radio.empty() && kernel::flight_running()) tick_radio();
    if (g_entries.empty()) return;
    find_gr3();
    scan_maps();
    // every 4th vertical blank: a reloaded overlay or table is redirected within 70 ms
    static int phase = 0;
    if (++phase & 3) return;
    int patched = 0;
    for (Entry& e : g_entries) {
        u32 field = e.a, orig = e.b;
        switch (e.kind) {
        case 'g': case 'n': case 'd': case 'e': case 'f':
            if (!g_gr3) continue;
            field += g_gr3;
            orig += g_gr3;
            break;
        case 'w': {
            if (!g_gr3) continue;
            field += g_gr3;
            if (mem::rd32(field) != e.c) continue;
            mem::copy_to_ee(e.addr, e.data.data(), e.data.size());
            mem::wr32(field, e.addr - (g_gr3 + e.b));
            patched++;
            continue;
        }
        case 'i': case 'j': {
            const u8* p = mem::ee_ptr(field);
            if (!p || memcmp(p, e.data.data(), e.data.size()) == 0) continue;
            if (!orig_ok(field, e.c)) continue;
            mem::copy_to_ee(field, e.data.data(), e.data.size());
            patched++;
            continue;
        }
        case 'k': {
            if (!g_gr3) continue;
            field += g_gr3;
            const u8* p = mem::ee_ptr(field);
            if (!p || memcmp(p, e.data.data(), e.data.size()) == 0) continue;
            if (fnv32(p, e.b) != e.c) continue;
            mem::copy_to_ee(field, e.data.data(), e.data.size());
            patched++;
            continue;
        }
        case 'm':
            continue;
        }
        if (field & 3 || !mem::ee_ptr(field) || mem::rd32(field) != orig) continue;
        if (!strchr("def", e.kind) && !orig_ok(orig, e.c)) continue;
        if (e.kind == 'n') {
            size_t len = strlen((const char*)mem::ee_ptr(orig));
            if (mem::rd8(field + 4) == len) mem::wr8(field + 4, (u8)std::min<size_t>(255, e.data.size() - 1));
        }
        mem::copy_to_ee(e.addr, e.data.data(), e.data.size());
        mem::wr32(field, e.addr);
        if (e.kind == 'd' || e.kind == 'e') {  // u16 length after / before the pointer
            u32 lf = e.kind == 'd' ? field + 4 : field - 4;
            u16 old = mem::rd16(lf);
            if (old == e.c || old == e.c + 1) mem::wr16(lf, (u16)e.len);
        }
        patched++;
    }
    if (patched) {
        static int logged = 0;
        if (logged++ < 20) log_write(LOG_MAIN, "translation sys: %d texts redirected", patched);
    }
}

}  // namespace systext
